beforeAll(async () => {
  await setup();
});
afterAll(async () => {
  await teardown();
});

test.concurrent('独立した処理', async () => {
  expect(await Promise.resolve(1)).toBe(1);
});

expect(() => {
  throw new Error('失敗');
}).toThrow('失敗');

test('取得', async () => {
  const value = await Promise.resolve(42);
  expect(value).toBe(42);
});

const fn = jest.fn((n: number) => n * 2);
fn(3);
expect(fn.mock.calls[0]).toEqual([3]);
expect(fn.mock.results[0].value).toBe(6);

jest.useFakeTimers();
const fn = jest.fn();
setTimeout(fn, 1000);
jest.advanceTimersByTime(1000);
expect(fn).toHaveBeenCalled();
jest.useRealTimers();

jest.useFakeTimers();
jest.setSystemTime(new Date('2026-01-01T00:00:00Z'));
expect(new Date().getUTCFullYear()).toBe(2026);
jest.useRealTimers();

export default {
  testEnvironment: 'node',
  clearMocks: true,
  restoreMocks: true
};
